        result[i] = 0;
      } else {
        result[i] = result[i - 1] + 1;
      }
    } else {
      if (i > 0) {
        int cur = a[i];
        int prev = a[i - 1];

        if (cur >= prev && (cur - prev) <= 2) {
          result[i] = result[i - 1] + 1;
        }
      }
    }
  }

  return result;
}

String fn0(String a) {
  if (a.isEmpty) {
    return '';
  }

  final List<String> parts = a.split(',');

  int total = 0;
  for (final String part in parts) {
    final int weight = part.codeUnitAt(0) - 64;
    final String tail = part.substring(1);
    final int value = int.parse(tail);
    total += weight * value;
  }

  int shift = total % 26;
  if (shift < 0) {
    shift += 26;
  }

  final List<String> out = <String>[];

  for (final String part in parts) {
    final int code = ((part.codeUnitAt(0) - 65 + shift) % 26) + 65;
    out.add(String.fromCharCode(code) + part.substring(1));
  }

  return out.join(',');
}
